// Secrets are optional during the first deployment, before secret bulk runs.
// Bindings and plain variables are generated by `wrangler types`; only secrets
// absent from Wrangler configuration are added here. Requests must fail closed
// when a secret is absent.
interface Env {
  ADMIN_TOKEN?: string;
  R2_ACCESS_KEY_ID?: string;
  R2_SECRET_ACCESS_KEY?: string;
}
